    public static Block registerBlocksWoodenFence(String string, Fence fence) {
        return Registry.register(Registries.BLOCK, string, fence);
    }

    public static Block registerBlocksWoodenFenceGate(String string, FenceGate fencegate) {
        return Registry.register(Registries.BLOCK, string, fencegate);
    }

    public static Block registerBlocksStoneWall(String string, Wall wall) {
        return Registry.register(Registries.BLOCK, string, wall);
    }

    public static Block registerBlocksWoodenWall(String string, WoodWall woodwall) {
        return Registry.register(Registries.BLOCK, string, woodwall);
    }

    public static Block registerBlocksMetalFence(String string, MetalFence metalfence) {
        return Registry.register(Registries.BLOCK, string, metalfence);
    }

    public static Block registerBlocksMetalFenceGate(String string, MetalFenceGate metalfencegate) {
        return Registry.register(Registries.BLOCK, string, metalfencegate);
    }

